script:
(function () {
  'use strict';

  var freqReadout = document.getElementById('freqReadout');
  var btnStop = document.getElementById('btnStop');
  var btnSweep = document.getElementById('btnSweep');
  var volumeSlider = document.getElementById('volumeSlider');
  var volumeValue = document.getElementById('volumeValue');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var toolError = document.getElementById('toolError');
  var freqButtons = Array.prototype.slice.call(document.querySelectorAll('.freq-btn'));
  var statBand = document.getElementById('statBand');
  var statHarmonic = document.getElementById('statHarmonic');
  var statVolumeNote = document.getElementById('statVolumeNote');
  var bandPreset = document.getElementById('bandPreset');
  var freqSlider = document.getElementById('freqSlider');
  var freqSliderValue = document.getElementById('freqSliderValue');
  var btnPlaySlider = document.getElementById('btnPlaySlider');
  var sweepStart = document.getElementById('sweepStart');
  var sweepEnd = document.getElementById('sweepEnd');
  var sweepLength = document.getElementById('sweepLength');
  var sweepRate = document.getElementById('sweepRate');
  var fadeTime = document.getElementById('fadeTime');
  var statLowest = document.getElementById('statLowest');
  var statFloorBand = document.getElementById('statFloorBand');

  var MAX_GAIN = 0.3; // conservative ceiling -- see this site's safety notes; low frequencies at high level risk driver damage
  var RAMP_SECONDS = 0.05;
  var MIN_HZ = 1, MAX_HZ = 200;

  var Ctor = window.AudioContext || window.webkitAudioContext;
  var audioCtx = null;
  var oscillator = null;
  var gainNode = null;
  var activeBtn = null;
  var sweeping = false;
  var sweepIntervalId = null;
  var sweep = null; // { f0, f1, T, start } frozen at sweep start

  function showError(msg) {
    if (!toolError) return;
    toolError.textContent = msg;
    toolError.classList.add('show');
  }
  function clearError() {
    if (!toolError) return;
    toolError.textContent = '';
    toolError.classList.remove('show');
  }

  function setDiagnostic(sev, html) {
    diagnosticPanel.innerHTML = '<div class="diagnostic-item' + (sev ? ' sev-' + sev : '') + '"><span class="diag-icon" aria-hidden="true">' +
      '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
      '</span><span>' + html + '</span></div>';
  }

  function formatFreq(hz) {
    var r = Math.round(hz * 10) / 10;
    return (r % 1 === 0 ? r.toFixed(0) : r.toFixed(1)) + ' Hz';
  }

  // Bands as in this tool's band presets.
  function bandName(hz) {
    if (hz < 10) return 'Infrasound';
    if (hz < 30) return 'Sub (10–30 Hz)';
    if (hz < 60) return 'Deep (30–60 Hz)';
    if (hz < 100) return 'Mid (60–100 Hz)';
    if (hz <= 200) return 'Upper (100–200 Hz)';
    return 'Above bass';
  }

  function showToneInfo(hz) {
    freqReadout.textContent = formatFreq(hz);
    statBand.textContent = bandName(hz);
    statHarmonic.textContent = formatFreq(hz * 2);
  }
  function clearToneInfo() {
    freqReadout.textContent = '—';
    statBand.textContent = '—';
    statHarmonic.textContent = '—';
  }

  function updateVolumeNote() {
    var v = parseFloat(volumeSlider.value);
    statVolumeNote.textContent = v <= 30 ? 'Low — safe start' : (v <= 60 ? 'Moderate' : 'High — risky');
  }

  function ensureContext() {
    if (!Ctor) {
      showError('Your browser doesn’t support the Web Audio API, so no bass tones can play here.');
      return Promise.reject(new Error('no-webaudio'));
    }
    if (!audioCtx) {
      try {
        audioCtx = new Ctor();
      } catch (e) {
        showError('The browser refused to start audio output: ' + (e && e.message ? e.message : e));
        return Promise.reject(e);
      }
      oscillator = audioCtx.createOscillator();
      gainNode = audioCtx.createGain();
      oscillator.type = 'sine';
      gainNode.gain.value = 0;
      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);
      oscillator.start();
    }
    return audioCtx.resume().then(function () { return audioCtx; }, function () { return audioCtx; });
  }

  function withContext(fn) {
    ensureContext().then(function () {
      clearError();
      fn();
    }).catch(function (e) {
      if (e && e.message === 'no-webaudio') return;
      showError('Audio could not start: ' + (e && e.message ? e.message : e));
    });
  }

  function currentGainTarget() {
    return (parseFloat(volumeSlider.value) / 100) * MAX_GAIN;
  }

  function rampGainTo(target) {
    if (!gainNode || !audioCtx) return;
    var now = audioCtx.currentTime;
    gainNode.gain.cancelScheduledValues(now);
    gainNode.gain.setValueAtTime(gainNode.gain.value, now);
    gainNode.gain.linearRampToValueAtTime(target, now + RAMP_SECONDS);
  }

  function setActive(btn) {
    if (activeBtn) { activeBtn.classList.remove('active'); activeBtn.setAttribute('aria-pressed', 'false'); }
    activeBtn = btn || null;
    if (activeBtn) { activeBtn.classList.add('active'); activeBtn.setAttribute('aria-pressed', 'true'); }
  }

  function readSweep() {
    var clamp = function (v, d) { v = parseFloat(v); if (!isFinite(v) || v <= 0) v = d; return Math.max(MIN_HZ, Math.min(MAX_HZ, v)); };
    var f0 = clamp(sweepStart.value, 20);
    var f1 = clamp(sweepEnd.value, 150);
    if (f0 === f1) f1 = f0 > 100 ? f0 / 2 : f0 * 2;
    var T = parseFloat(sweepLength.value);
    if (!isFinite(T) || T <= 0) T = 10;
    T = Math.max(1, Math.min(600, T));
    return { f0: f0, f1: f1, T: T };
  }

  function updateSweepInfo() {
    var s = readSweep();
    if (!sweeping) btnSweep.textContent = 'Start Sweep (' + (Math.round(s.T * 10) / 10) + 's)';
    sweepRate.textContent = (Math.abs(s.f1 - s.f0) / s.T).toFixed(2) + ' Hz per second';
    updateLowest();
  }

  // Lowest frequency heard = where the (exponential) sweep was at the
  // second the visitor says the bass faded.
  function updateLowest() {
    var t = parseFloat(fadeTime.value);
    if (!isFinite(t) || t < 0) { statLowest.textContent = '—'; statFloorBand.textContent = '—'; return; }
    var s = readSweep();
    var f = s.f0 * Math.pow(s.f1 / s.f0, Math.min(1, t / s.T));
    statLowest.textContent = formatFreq(f) + (t > s.T ? ' (sweep end)' : '');
    statFloorBand.textContent = bandName(f);
  }

  function stopSweep() {
    if (sweepIntervalId) { clearInterval(sweepIntervalId); sweepIntervalId = null; }
    if (sweeping && oscillator && audioCtx) {
      var now = audioCtx.currentTime;
      var f = oscillator.frequency.value;
      oscillator.frequency.cancelScheduledValues(now);
      oscillator.frequency.setValueAtTime(f, now);
    }
    sweeping = false;
    sweep = null;
    updateSweepInfo();
  }

  function stopAll() {
    stopSweep();
    rampGainTo(0);
    setActive(null);
    btnStop.disabled = true;
    clearToneInfo();
  }

  function playFrequency(freq, btn) {
    stopSweep();
    withContext(function () {
      var now = audioCtx.currentTime;
      oscillator.frequency.cancelScheduledValues(now);
      oscillator.frequency.setValueAtTime(freq, now);
      rampGainTo(currentGainTarget());
      setActive(btn);
      btnStop.disabled = false;
      showToneInfo(freq);
      setDiagnostic('ok', '<strong>Playing ' + formatFreq(freq) + '.</strong> If you hear nothing and your speaker is small, that\'s likely a hardware limitation, not a fault -- see the guide alongside this.');
    });
  }

  // The oscillator follows an exponential ramp scheduled on the audio clock
  // (smooth, works rising or falling); the timer only updates the readout
  // and ends the run -- timer-driven rather than requestAnimationFrame so a
  // briefly backgrounded tab still finishes on schedule.
  function startSweep() {
    if (sweeping) { stopAll(); setDiagnostic('', 'Stopped.'); return; }
    withContext(function () {
      setActive(null);
      var s = readSweep();
      var now = audioCtx.currentTime;
      oscillator.frequency.cancelScheduledValues(now);
      oscillator.frequency.setValueAtTime(s.f0, now);
      oscillator.frequency.exponentialRampToValueAtTime(s.f1, now + s.T);
      sweep = { f0: s.f0, f1: s.f1, T: s.T, start: now };
      sweeping = true;
      btnSweep.textContent = 'Stop Sweep';
      btnStop.disabled = false;
      rampGainTo(currentGainTarget());
      showToneInfo(s.f0);
      setDiagnostic('ok', '<strong>Sweeping ' + formatFreq(s.f0) + ' → ' + formatFreq(s.f1) + '…</strong> Listen for any point where a rattle appears or the sound drops out' + (s.f1 < s.f0 ? ', and note the second the bass fades.' : '.'));
      sweepIntervalId = setInterval(tickSweep, 40);
    });
  }

  function tickSweep() {
    if (!sweeping || !audioCtx) return;
    var t = audioCtx.currentTime - sweep.start;
    if (t >= sweep.T) {
      stopAll();
      setDiagnostic('ok', '<strong>Sweep finished.</strong> Note the frequency shown if you heard a rattle or dropout.');
      return;
    }
    showToneInfo(sweep.f0 * Math.pow(sweep.f1 / sweep.f0, t / sweep.T));
  }

  function sliderFreq() {
    return parseFloat(freqSlider.value) || 60;
  }

  freqButtons.forEach(function (btn) {
    btn.setAttribute('aria-pressed', 'false');
    btn.addEventListener('click', function () {
      playFrequency(parseFloat(btn.getAttribute('data-freq')), btn);
    });
  });

  btnPlaySlider.addEventListener('click', function () {
    if (activeBtn === btnPlaySlider) { stopAll(); setDiagnostic('', 'Stopped.'); return; }
    playFrequency(sliderFreq(), btnPlaySlider);
  });
  freqSlider.addEventListener('input', function () {
    var f = sliderFreq();
    freqSliderValue.textContent = formatFreq(f);
    bandPreset.value = 'custom';
    if (activeBtn === btnPlaySlider && audioCtx) {
      oscillator.frequency.setTargetAtTime(f, audioCtx.currentTime, 0.015);
      showToneInfo(f);
    }
  });
  // A band preset jumps the slider to the middle of that bass range.
  bandPreset.addEventListener('change', function () {
    if (bandPreset.value === 'custom') return;
    var f = parseFloat(bandPreset.value);
    freqSlider.value = f;
    freqSliderValue.textContent = formatFreq(f);
    playFrequency(f, btnPlaySlider);
  });

  btnStop.addEventListener('click', function () {
    stopAll();
    setDiagnostic('', 'Stopped.');
  });
  btnSweep.addEventListener('click', startSweep);
  [sweepStart, sweepEnd, sweepLength].forEach(function (el) {
    el.addEventListener('input', updateSweepInfo);
  });
  fadeTime.addEventListener('input', updateLowest);

  volumeSlider.addEventListener('input', function () {
    volumeValue.textContent = volumeSlider.value + '%';
    updateVolumeNote();
    if ((activeBtn || sweeping) && audioCtx) rampGainTo(currentGainTarget());
  });

  window.addEventListener('pagehide', function () {
    stopSweep();
    setActive(null);
    if (audioCtx) { audioCtx.close().catch(function () {}); audioCtx = null; }
    oscillator = null;
    gainNode = null;
  });
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') {
      stopAll();
      if (audioCtx && audioCtx.state === 'running') audioCtx.suspend().catch(function () {});
    }
  });

  updateVolumeNote();
  updateSweepInfo();

  if (!Ctor) {
    setDiagnostic('error', '<strong>Your browser doesn’t support the Web Audio API.</strong>');
    freqButtons.forEach(function (b) { b.disabled = true; });
    btnSweep.disabled = true;
    btnPlaySlider.disabled = true;
  }
})();
